  ('afff7379-6985-5efc-a275-2c6435c022db', null, (select id from public.skills where slug = 'read-g7-authors-purpose'), null, 'medium',
   $q$How does the author respond to the historians who want to keep the sign?$q$, $q$[{"text":"The author says their facts are false and that Marisol held the official title.","is_correct":false,"misconception_token":"misreads-concession"},{"text":"The author ignores their argument and talks only about the fishing fleet.","is_correct":false,"misconception_token":"misses-counterargument"},{"text":"The author agrees with their facts but argues a title does not show who did the work.","is_correct":true},{"text":"The author agrees with them completely and decides the sign is good enough.","is_correct":false,"misconception_token":"reverses-position"}]$q$::jsonb, $q$The author agrees with their facts but argues a title does not show who did the work.$q$, $q$The author writes "That is true" and then adds, "But an official title does not show who climbed the stairs." The author accepts their facts, so the author does not call them false.$q$, 'draft', 'eafa22fb-ff01-57f2-a13a-058b0e050868')
