  ('0bf686b7-9676-5d90-8185-6d53176de95d', null, (select id from public.skills where slug = 'read-g7-authors-purpose'), null, 'medium',
   $q$Which sentence from the passage most directly states the author's position?$q$, $q$[{"text":"\"The city council will vote on the repainting plan in May.\"","is_correct":false,"misconception_token":"detail-not-claim"},{"text":"\"I propose a different plan: invite students from the three nearby schools to design and paint a mural there.\"","is_correct":true},{"text":"\"The city's public works director has raised two concerns.\"","is_correct":false,"misconception_token":"confuses-opposing-view"},{"text":"\"The concrete walls of the Lindell Street underpass are gray, cracked, and often covered in scribbled tags.\"","is_correct":false,"misconception_token":"detail-not-claim"}]$q$::jsonb, $q$"I propose a different plan: invite students from the three nearby schools to design and paint a mural there."$q$, $q$This sentence says exactly what the author wants to happen. The others describe the setting, the director's concerns, or the timing of the vote without stating the author's position.$q$, 'draft', '149f235a-7156-50bf-a282-bd3f18a3be01')
